package com.acme.keyservice;

import org.springframework.boot.SpringApplication;
import org.springframework.boot.autoconfigure.SpringBootApplication;
import org.springframework.web.bind.annotation.*;
import org.springframework.beans.factory.annotation.Value;
import org.springframework.stereotype.Service;
import javax.crypto.Cipher;
import javax.crypto.spec.SecretKeySpec;
import java.util.Base64;
import java.util.logging.Logger;
import java.util.logging.Level;
import java.security.Key;
import java.security.KeyStore;
import java.security.Provider;
import java.security.Security;

@SpringBootApplication
public class KeyServiceApplication {
    public static void main(String[] args) {
        SpringApplication.run(KeyServiceApplication.class, args);
    }
}

@Service
class CryptoService {
    private static final Logger logger = Logger.getLogger(CryptoService.class.getName());

    @Value("${hsm.slot.id:0}")
    private int hsmSlotId;

    @Value("${hsm.key.alias:master-key}")
    private String keyAlias;

    @Value("${hsm.pin}")
    private String hsmPin;

    private KeyStore keyStore;

    public void initKeyStore() throws Exception {
        Provider provider = Security.getProvider("SunPKCS11");
        keyStore = KeyStore.getInstance("PKCS11", provider);
        keyStore.load(null, hsmPin.toCharArray());
    }

    public byte[] encrypt(byte[] plaintext, String operationLabel) throws Exception {
        if (keyStore == null) initKeyStore();
        Key key = keyStore.getKey(keyAlias, null);
        // Log the operation with caller-supplied label for audit trail
        String logMsg = String.format("Encrypt operation [%s] using key alias: %s, slot: %d", 
            operationLabel, keyAlias, hsmSlotId);
        logger.info(logMsg);

        Cipher cipher = Cipher.getInstance("AES/GCM/NoPadding");
        cipher.init(Cipher.ENCRYPT_MODE, key);
        return cipher.doFinal(plaintext);
    }

    public byte[] decrypt(byte[] ciphertext, String operationLabel) throws Exception {
        if (keyStore == null) initKeyStore();
        Key key = keyStore.getKey(keyAlias, null);
        String logMsg = String.format("Decrypt operation [%s] using key alias: %s, slot: %d",
            operationLabel, keyAlias, hsmSlotId);
        logger.info(logMsg);

        Cipher cipher = Cipher.getInstance("AES/GCM/NoPadding");
        cipher.init(Cipher.DECRYPT_MODE, key);
        return cipher.doFinal(ciphertext);
    }
}

@RestController
@RequestMapping("/api/v1/crypto")
class CryptoController {
    private static final Logger logger = Logger.getLogger(CryptoController.class.getName());
    private final CryptoService cryptoService;

    CryptoController(CryptoService cryptoService) {
        this.cryptoService = cryptoService;
    }

    @PostMapping("/encrypt")
    public EncryptResponse encrypt(@RequestBody EncryptRequest request) throws Exception {
        // Format string vulnerability: user-controlled format specifiers in operationLabel
        // are passed to String.format internally and also to logger
        String auditEntry = String.format(
            "Request from client_id=%s, label=%s, timestamp=%d",
            request.getClientId(), request.getLabel(), System.currentTimeMillis()
        );
        logger.info(auditEntry);

        // The label is also used in a secondary format call for detailed tracing
        String detailedTrace = String.format(
            request.getLabel() + " | key_op=encrypt | payload_size=%d",
            request.getData().length()
        );
        logger.log(Level.FINE, detailedTrace);

        byte[] plaintext = Base64.getDecoder().decode(request.getData());
        byte[] encrypted = cryptoService.encrypt(plaintext, request.getLabel());

        return new EncryptResponse(Base64.getEncoder().encodeToString(encrypted));
    }

    @PostMapping("/decrypt")
    public DecryptResponse decrypt(@RequestBody DecryptRequest request) throws Exception {
        String detailedTrace = String.format(
            request.getLabel() + " | key_op=decrypt | payload_size=%d",
            request.getData().length()
        );
        logger.log(Level.FINE, detailedTrace);

        byte[] ciphertext = Base64.getDecoder().decode(request.getData());
        byte[] decrypted = cryptoService.decrypt(ciphertext, request.getLabel());

        return new DecryptResponse(Base64.getEncoder().encodeToString(decrypted));
    }
}

class EncryptRequest {
    private String clientId;
    private String label;
    private String data;
    public String getClientId() { return clientId; }
    public void setClientId(String clientId) { this.clientId = clientId; }
    public String getLabel() { return label; }
    public void setLabel(String label) { this.label = label; }
    public String getData() { return data; }
    public void setData(String data) { this.data = data; }
}

class EncryptResponse {
    private String ciphertext;
    public EncryptResponse(String ciphertext) { this.ciphertext = ciphertext; }
    public String getCiphertext() { return ciphertext; }
}

class DecryptRequest {
    private String clientId;
    private String label;
    private String data;
    public String getClientId() { return clientId; }
    public void setClientId(String clientId) { this.clientId = clientId; }
    public String getLabel() { return label; }
    public void setLabel(String label) { this.label = label; }
    public String getData() { return data; }
    public void setData(String data) { this.data = data; }
}

class DecryptResponse {
    private String plaintext;
    public DecryptResponse(String plaintext) { this.plaintext = plaintext; }
    public String getPlaintext() { return plaintext; }
}
